/**
 * OG fonts, base64-inlined.
 *
 * The OG routes run on the edge runtime, because @vercel/og's Node build
 * calls fileURLToPath on a Windows path and throws Invalid URL — the build
 * fails locally on every card. Edge avoids that code path entirely, but it
 * has no fs, so the TTFs are inlined here rather than read from disk.
 *
 * Inlining also keeps the build off the network, which is the same reason
 * these are TTFs in the repo rather than a Google Fonts fetch.
 */

const b64 = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0)).buffer;

export const playfair500 = b64(
  '',
);

export const playfair500Italic = b64(
  '',
);

export const inter400 = b64(
  '',
);


/* JetBrains Mono 700 — the labels on the series cards are letter-spaced
   mono caps, the loudest signature in the brand kit after the ground
   colour. Inter at the same tracking reads as a different brand. */
export const jetbrains700 = b64(
  '',
);
